func decode(_ data: Data) -> (String, String)? {
    for (name, encoding) in [("utf8", String.Encoding.utf8), ("utf16", .utf16), ("cp1252", .windowsCP1252), ("latin1", .isoLatin1)] {
        if let text = String(data: data, encoding: encoding) { return (name, text) }
    }
