    } else {
        print("\(label): bytes=\(data.count) not decoded")
    }
}

let body = "1\n00:00:01,000 --> 00:00:02,000\nCafé déjà vu\n\n2\n00:00:03,000 --> 00:00:04,000\nÉté\n"
