    show("utf16 BOM \(tag)", text.data(using: .utf16)!)
    show("utf16LE noBOM \(tag)", text.data(using: .utf16LittleEndian)!)
    show("utf16BE noBOM \(tag)", text.data(using: .utf16BigEndian)!)
}
